/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {

    function renameTypeKey(payload, oldKey, newKey) {
        const {
            [oldKey]: replaceByKey, ...rest
        } = payload;
        return {
            ...rest,
            [newKey]: replaceByKey
        };
    }


    const payload = api.context.props.payload;
    const route = payload.type.route;

    return {
        viewportElementId: 'viewport_hxr',
        route: route,
        params: {
            payload: renameTypeKey(payload, 'type', 'ctype')
        }
    };
}

